"""Reconstruct the full trial readout plan from pinned immutable source bytes."""
from pathlib import Path
import argparse,json,gzip,hashlib,struct
ap=argparse.ArgumentParser();ap.add_argument('--repo',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();a.out.mkdir(parents=True,exist_ok=False);R=a.repo;H=lambda b:hashlib.sha256(b).hexdigest()
C=R/'captures/2026-10-20T234200Z-codex-weighted-conditioning-d6af1d67';pb=(C/'PROPOSAL_FREEZE.json').read_bytes();assert H(pb)=='7572aa3452ede3e283bd850014f443759e0ff0d181f30815d5b8be3d7a209517';pr=json.loads(pb);packed=(C/'Q_DYADIC.bin.gz').read_bytes();assert H(packed)==pr['Q_gzip_sha256']=='fb9c4ea700d9624bf7894c4c138a2cf7874856a25d32e1b739b842a69672a33d';q=gzip.decompress(packed);assert H(q)==pr['Q_decoded_sha256']=='f99676245536fff6220278ac1d700c67df84489671b85f0f773a80d8c7efbb71';assert len(q)==2640*1999*8
op=gzip.decompress((R/'captures/2026-10-21T013801Z-codex-source-actions-9c7b87b9/OPERATOR.txt.gz').read_bytes());assert H(op)=='cca3ed7e671b8397c3940921d9845399425fd2558cc62708941c00fc4b899950';obs=list(map(int,op.decode().splitlines()[1].split()));assert len(obs)==62
get=lambda r,c:struct.unpack_from('<q',q,(r*1999+c)*8)[0];cols=[]
for c in range(1999):
 i=c if c<1000 else c-999;cols.append({'column':c,'mode':'zero'if c==0 else('u'if c<1000 else'v'),'frequency_integer':pr['frequency_integers'][i],'a':[get(r,i)for r in obs],'b':[0]*62 if c==0 else[get(r,999+i)for r in obs]})
sl={'columns':cols,'source_proposal_sha256':H(pb),'Q_decoded_sha256':H(q),'operator_sha256':H(op),'full_required_rows':1999,'constructed_plan_rows':1999};sb=(json.dumps(sl,indent=2,sort_keys=True)+'\n').encode();(a.out/'FULL_SLICE.json').write_bytes(sb);(a.out/'OPERATOR.txt').write_bytes(op)
old=R/'captures/2026-10-21T022602Z-codex-reusable-compression-8fd46991';oldsl=json.loads((old/'TRIAL_SLICE.json').read_text());assert all(cols[v['column']]==v for v in oldsl['columns']);fb=(old/'frame/PARTIAL_FRAME.json').read_bytes();assert H(fb)=='1c8e2f214c7e832afbaff324524a12dc3dbdd9bb126e031d2a71f84c437fe015';resultb=(old/'RESULT.json').read_bytes();assert H(resultb)=='3d66e023592dcc9dbc96005021e7beb18dc4599055aa6326c3b355c773559357'
source={'status':'PASS_FULL1999_SOURCE_PLAN_BEFORE_CONSTRUCTION','full_slice_sha256':H(sb),'operator_sha256':H(op),'proposal_sha256':H(pb),'Q_packed_sha256':H(packed),'Q_decoded_sha256':H(q),'parent_C32_result_sha256':H(resultb),'reuse_frame_receipt_sha256':H(fb),'planned_rows':1999,'planned_reused_rows':16,'planned_new_rows':1983,'nonzero_phase_frequencies':len(set(r['frequency_integer']for r in cols if r['mode']!='zero')),'physical_promotion':0,'external_promotion_review':'PENDING'};(a.out/'SOURCE_PLAN.json').write_text(json.dumps(source,indent=2,sort_keys=True)+'\n');print(json.dumps(source,indent=2))
